function parseLokiResponse(resp) {
  if (!resp || !resp.data) return [];
  const streams = resp.data.result || [];
  const out = [];
  for (const stream of streams) {
    for (const pair of (stream.values || [])) {
      const line = pair[1];
      try { out.push(JSON.parse(line)); } catch (e) {}
    }
  }
  return out;
}
function parseFluxCsv(text) {
