  const lines = text.split(/\r?\n/).filter(function (l) { return l.length > 0; });
  let headers = null;
  const rows = [];
  for (const line of lines) {
    if (line.startsWith('#')) continue;
    if (!headers) { headers = line.split(','); continue; }
    const fields = line.split(',');
    const row = {};
    for (let i = 0; i < headers.length; i++) {
      const h = (headers[i] || '').trim();
      if (!h || h === 'result' || h === 'table') continue;
      const v = (fields[i] || '').trim();
      const num = Number(v);
      row[h] = (v !== '' && !isNaN(num)) ? num : v;
    }
    rows.push(row);
  }
  return rows;
}
